VID.narration = {"look":{"bar":false},"scenes":[{"dur":9.288,"caps":[[0.5,7.39,"Algorithms, phase five. Convex hulls. This is how computers find the outline of a crowd."]],"warp":[[0,0],[0.5,0.9],[9.288,4]]},{"dur":23.336,"caps":[[0.72,5.21,"Stretch a rubber band round every pin."],[5.46,9.22,"Let go. It snaps onto the outer pins."],[9.47,13.32,"The pins it touches are the hull corners."],[13.57,16.86,"A dent lets a segment poke outside."],[17.11,22.08,"A convex shape keeps every segment inside."]],"warp":[[0,0],[0.715,1.3],[5.455,3.7],[9.475,5.5],[13.575,8.6],[17.115,10.5],[23.336,14]]},{"dur":23.336,"caps":[[0.5,4.83,"Walk from p to a to b. Left or right?"],[5.08,10.37,"Multiply across, subtract: positive means left."],[10.62,12.55,"Now try a different path."],[12.8,17.05,"Negative means a right turn."],[17.3,18.91,"And one more path."],[19.16,22.77,"Zero means a straight line."]],"warp":[[0,0],[0.5,0.6],[5.08,2.8],[10.62,6.2],[12.8,8.3],[17.3,10],[19.16,12.1],[23.336,14]]},{"dur":16.788,"caps":[[0.55,3.92,"Walk round the hull, corner by corner."],[4.17,7.94,"Anticlockwise, every turn is a left turn."],[8.19,11.64,"Go through F and you turn right."],[11.89,15.1,"Right turn: a dent, not a corner."]],"warp":[[0,0],[0.55,1],[4.17,5],[8.19,6.3],[11.89,8.6],[16.788,11]]},{"dur":36.548,"caps":[[0.5,5.07,"A computer has no rubber band. Way one: wrap."],[5.32,9.73,"The leftmost point must be on the hull."],[9.98,14.31,"Swing a line clockwise from r."],[14.56,17.61,"Every point it touches gets an angle."],[17.86,22.75,"Smallest angle wins: A to G."],[23,27.01,"Repeat from G. Start the swing along the last edge."],[27.26,31.03,"Each round, the first point touched is the next corner."],[31.28,35.53,"Back at A. One sweep per corner: 5 sweeps."]],"warp":[[0,0],[0.5,0.3],[5.32,2],[9.98,3.6],[14.56,5],[17.86,6.8],[23,8],[27.26,10.1],[31.28,14.6],[36.548,16.7]]},{"dur":19.993,"caps":[[0.5,3.47,"Way two: sort the points first."],[3.72,6.61,"The lowest point must be on the hull."],[6.86,11.03,"Sort the rest by angle, sweeping anticlockwise."],[11.28,14.01,"Walk the points in this order."],[14.26,18.19,"The path still has dents."]],"warp":[[0,0],[0.5,0.3],[3.72,1.8],[6.86,3.1],[11.28,6.5],[14.26,8.2],[19.993,11]]},{"dur":21.664,"caps":[[0.5,3.07,"Start the stack with C and D."],[3.32,5.89,"Left turn: keep the middle point."],[6.14,9.19,"A right turn is a dent: pop it."],[9.44,12.17,"Left turn again: push B."],[12.42,16.35,"A right turn again: pop B, then push A."],[16.6,21.09,"The stack is the hull. One pass after the sort."]],"warp":[[0,0],[0.5,0.8],[3.32,3.2],[6.14,6],[9.44,8.5],[12.42,10.5],[16.6,13.3],[21.664,15]]},{"dur":45.116,"caps":[[0.55,4.88,"1,024 points, and only 4 are corners."],[5.13,7.54,"One sweep checks all 1,024 points."],[7.79,13.4,"4 corners, 4 sweeps: 4,096 steps."],[13.65,16.7,"A sort halves the list again and again."],[16.95,22.4,"Ten halvings: log₂ 1,024 = 10."],[22.65,28.26,"The sort makes 10 passes: about 10,240 steps."],[28.51,31,"Few corners: wrapping wins."],[31.25,33.58,"Now every point is a corner."],[33.83,38.56,"At 10 corners they tie. More, and wrapping loses."],[38.81,44.18,"Scan wins. Wrapping costs about 100 times more."]],"warp":[[0,0],[0.55,1],[5.13,2.5],[7.79,4.1],[13.65,6],[16.95,7.8],[22.65,9.1],[28.51,10.8],[31.25,12.3],[33.83,13.8],[38.81,15.4],[45.116,17.6]]},{"dur":28.236,"caps":[[0.55,4.96,"Try every pair: 21 of them."],[5.21,10.18,"The farthest pair is A and E: two corners."],[10.43,14.04,"An inside point always loses to a corner."],[14.29,18.14,"So drop every pair that uses an inside point."],[18.39,22.32,"1,000 points, 10 corners."],[22.57,27.46,"45 pairs to check, not 499,500."]],"warp":[[0,0],[0.55,1],[5.21,3.5],[10.43,5.5],[14.29,7.6],[18.39,10.6],[22.57,12.4],[28.236,14.6]]},{"dur":18.738,"caps":[],"warp":[[0,0],[0.5,0.9],[3.72,1.8],[8.38,2.7],[13.84,3.6],[18.738,10]]}]};
